def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    color = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]

    out = [row[:] for row in grid]
    for top in range(h - (r1-r0)):
        for left in range(w - (c1-c0)):
            if (top, left) == (r0, c0):
                continue
            cells = [(top+dr, left+dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out
